        for c in range(w):
            col=grid[r][c]
            if col==bg or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); pts=[]
            while q:
                y,x=q.pop(); pts.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    z=(y+dy,x+dx)
                    if 0<=z[0]<h and 0<=z[1]<w and z not in seen and grid[z[0]][z[1]]==col:
                        seen.add(z); q.append(z)
            comps.append((col,pts))
    def forms(pts):
        out=set()
        for reflect in (1,-1):
            for rot in range(4):
                a=[]
                for y,x in pts:
                    x*=reflect
                    for _ in range(rot): y,x=x,-y
                    a.append((y,x))
                my=min(y for y,x in a); mx=min(x for y,x in a)
                out.add(tuple(sorted((y-my,x-mx) for y,x in a)))
        return out
    fs=[forms(pts) for col,pts in comps]
    # An object that repeats another object's shape takes the other's color.
    for i,(col,pts) in enumerate(comps):
        for j,(other,_) in enumerate(comps):
            if i!=j and col!=other and fs[i]&fs[j]:
